-- Validação somente leitura da página COM cursor de dbo.Divida_Conta_Corrente.
-- Valores sintéticos (não são dados de produção). Não cria índice, não altera dados nem timeout.
-- ORDER BY de cada ramo fica numa subconsulta com TOP. O UNION ALL não tem ORDER BY.
-- Cada parâmetro entra com CAST para o tipo da coluna (varchar, int ou datetime), para o Seek não virar Scan.
-- pymssql entrega texto como nvarchar; o CAST fica no parâmetro, não na coluna.
-- Sequencia é int: a fixture da origem grava número. CODI é varchar(22) e SEQU varchar(4), as larguras da prata.
-- Não foi executado neste repositório: não há SQL Server aqui.
--
-- 1) Sintaxe, sem compilar e sem executar.
-- 2) Plano estimado. SET SHOWPLAN_XML precisa ser o único comando do lote (GO).
--    Compilar o plano lê estatísticas; não executa a consulta. Pode demorar na tabela real.

SET PARSEONLY ON;
SELECT TOP (1000) [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO], [Vr_Pago], [Compo] FROM (SELECT [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO], [Vr_Pago], [Compo] FROM (SELECT TOP (1000) [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO], [Vr_Pago], [Compo] FROM [dbo].[Divida_Conta_Corrente] WHERE [Data_Movimentacao] = CAST('2024-01-01T00:00:00' AS datetime) AND [Sequencia] = CAST(1 AS int) AND [CODI] = CAST(N'A' AS varchar(22)) AND [SEQU] = CAST(N'00' AS varchar(4)) AND [ANO] > CAST(2020 AS int) ORDER BY [ANO]) AS [ramo0] UNION ALL SELECT [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO], [Vr_Pago], [Compo] FROM (SELECT TOP (1000) [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO], [Vr_Pago], [Compo] FROM [dbo].[Divida_Conta_Corrente] WHERE [Data_Movimentacao] = CAST('2024-01-01T00:00:00' AS datetime) AND [Sequencia] = CAST(1 AS int) AND [CODI] = CAST(N'A' AS varchar(22)) AND [SEQU] > CAST(N'00' AS varchar(4)) ORDER BY [SEQU], [ANO]) AS [ramo1] UNION ALL SELECT [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO], [Vr_Pago], [Compo] FROM (SELECT TOP (1000) [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO], [Vr_Pago], [Compo] FROM [dbo].[Divida_Conta_Corrente] WHERE [Data_Movimentacao] = CAST('2024-01-01T00:00:00' AS datetime) AND [Sequencia] = CAST(1 AS int) AND [CODI] > CAST(N'A' AS varchar(22)) ORDER BY [CODI], [SEQU], [ANO]) AS [ramo2] UNION ALL SELECT [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO], [Vr_Pago], [Compo] FROM (SELECT TOP (1000) [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO], [Vr_Pago], [Compo] FROM [dbo].[Divida_Conta_Corrente] WHERE [Data_Movimentacao] = CAST('2024-01-01T00:00:00' AS datetime) AND [Sequencia] > CAST(1 AS int) ORDER BY [Sequencia], [CODI], [SEQU], [ANO]) AS [ramo3] UNION ALL SELECT [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO], [Vr_Pago], [Compo] FROM (SELECT TOP (1000) [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO], [Vr_Pago], [Compo] FROM [dbo].[Divida_Conta_Corrente] WHERE [Data_Movimentacao] > CAST('2024-01-01T00:00:00' AS datetime) ORDER BY [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO]) AS [ramo4]) AS [pagina] ORDER BY [Data_Movimentacao], [Sequencia], [CODI], [SEQU], [ANO];
SET PARSEONLY OFF;
GO

SET SHOWPLAN_XML ON;
